# pricing.py
import math


def simple_return(p0, p1):
    return p1 / p0 - 1


def log_return(p0, p1):
    return math.log(p1 / p0)

from statistics import mean, stdev


def band(closes):
    m = mean(closes)
    s = stdev(closes)
    return (round(m - 2 * s, 2), round(m + 2 * s, 2))

